# The companion that plays the second launch of the removal chain: a game saved with Colorful Coats - Dodos! Renew,
# loaded without it. Run with:
#   -DepMap wsl-deps.removal.map -Filter '08-removal-write' -Then 'removal-check' -ThenWithout 'nelim.colorfulcoats.dodos','nelim.colorfulcoats.dodos.pickletests'
#
# The companion has no dependency on the dodos mod, which is the point; `-ThenWithout` takes the mod and its test
# companion out of the list before the second launch, and this one stays. The path is relative to the collection's
# root, and the folder's own About.xml packageId must equal the one written here. `-Then` plays on the local WSL only.
OskarPotocki.VanillaFactionsExpanded.Core 2023507013
nelim.colorfulcoats.dodos.pickleremoval path:ColorfulCoatsDodosRenew/Tests/Pickle/Removal/Mod
nelim.pickletools.coatsteps path:PickleTools/CoatSteps/Mod
nelim.pickletools.savesteps path:PickleTools/SaveSteps/Mod
